// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testRegression_property() public {
        vm.warp(1000);
        vm.roll(15);

        address alice = address(0xA11CE);
        vm.deal(alice, 10 ether);

        vm.prank(alice);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);

        vm.deal(alice, 10 ether);
        vm.prank(alice);
        (bool ok2,) = address(c).call{value: 10 ether}("");


        c = new Roulette();
        vm.warp(1);
        vm.roll(15);
        vm.deal(alice, 10 ether);
        vm.prank(alice);
        (bool okFirst,) = address(c).call{value: 10 ether}("");
        assertTrue(okFirst);

        vm.warp(2);
        vm.deal(alice, 10 ether);
        vm.prank(alice);
        (bool okSecond,) = address(c).call{value: 10 ether}("");


        assertTrue(!okSecond);
    }
}
